text:
// Pawn Champ - Waypoints. Major quest M24, batch G (docs/quests/MAJOR.md#m24-waypoints).
// Somebody is dragging the closed scallop bed off Gannet Island at night. A young deckhand pawns
// the boat's chartplotter, and its saved track says whose boat it is: Tess Bascombe's nephew's.
//
// Hook (W1 Tue)             Jo Pinto pawns a cracked chartplotter "from a dumpster".
// Rumour (W1 Thu)           Tess Bascombe: someone is running dark on the closed bed.
// Middle (W2 Mon, Tue)      Bento Raposo wants it back; Jo comes clean and asks you aboard.
// Scene 1 (W2 Wed-W3 Mon)   the Bonnie Dee's wheelhouse at the pier, in the rain: the track.
// Scene 2 (W3 Mon-Thu)      the run at 2 a.m. with every light off; the dredge comes up.
// Finale (W3 Thu-W4 Thu)    the hearing at the harbormaster's shack.
// Crossing: Static on Channel 16 (M9): the plotter has the Margaret Ruth's position saved.
//
// Written as data: docs/STORY_DATA.md. Strict JSON inside the call.
defineStory({
  "id": "plotter",
  "kind": "major",
  "colour": "#3aa03a",
  "family": "crime",
  "title": "Waypoints",
  "crosses": ["radio"],
  "rumour": "Somebody's been dragging the closed scallop bed off Gannet. At night, lights off.",
  "endings": { "hearing": "On the Record", "family": "Family Business", "overboard": "Lost at Sea", "sold": "Sold the Waypoints" },
  "icons": {
    "plotter": [
      "............",
      ".kkkkkkkkkk.",
      ".kddddddddk.",
      ".kdggggGgdk.",
      ".kdgGgggGdk.",
      ".kdggGGggdk.",
      ".kdgggggGdk.",
      ".kddddddddk.",
      ".kdsdsdsddk.",
      ".kddddddddk.",
      ".kkkkkkkkkk.",
      "............"
    ],
    "bigshell": [
      "............",
      ".....kk.....",
      "...kkppkk...",
      "..kppPpppk..",
      ".kpPppPppPk.",
      ".kpPppPppPk.",
      "kppPppPppPpk",
      "kppPppPppPpk",
      ".kppPpPpPpk.",
      "..kkkppkkk..",
      "....kkkk....",
      "............"
    ]
  },
  "about": [
    "A fishing story about a closed scallop bed. Jo Pinto pawns a cracked chartplotter she says came from a dumpster (§{joPlotter}). Tess, the harbormaster, tells you someone is dragging the closed bed off Gannet at night with their lights off, and asks to hear if a plotter turns up (§{tessBed}). Showing her then ends it quietly (Family Business). Bento Raposo offers $150 to have \"his\" plotter back (§{bentoPlotter}); selling ends it (Sold the Waypoints).",
    "Jo comes clean (§{joBack}): she took it off the dash of the boat she crews on. In the wheelhouse in the rain (§{plotterWheelhouse}) the tracks show fourteen night trips on the closed bed by Kenny Bascombe, a good skipper behind on his loan and Tess's nephew. You go out with them one night (§{plotterRun}) and see the haul. A camera gets you proof.",
    "At the hearing at the harbormaster's shack (§{plotterHearing}) you can put the plotter or your photos on the table (On the Record), give it to Tess privately outside (Family Business), say it went over the side (Lost at Sea), or sell the waypoints to Bento afterwards (Sold the Waypoints)."
  ],
  "cast": {
    "jo": {
      "name": "Jo Pinto",
      "look": { "skin": "#c89070", "hair": "#1a1410", "hs": 1, "coat": "#e8a020", "trim": "#2a2a2a", "style": "puffer", "hat": "beanie", "hatc": "#2a4a6a", "pants": "#3a4a3a" }
    },
    "kenny": {
      "name": "Kenny Bascombe",
      "look": { "skin": "#e8c0a0", "hair": "#8a5a3a", "hs": 0, "coat": "#3a5a3a", "style": "hoodie", "trim": "#e8e4dc", "hat": "cap", "hatc": "#c83a2a", "pants": "#2a3a4a", "beard": "#8a5a3a" }
    },
    "bento": {
      "name": "Bento Raposo",
      "look": { "skin": "#b88060", "hair": "#5a5a5a", "hs": 2, "coat": "#2a3a5a", "trim": "#e8e4dc", "style": "jacket", "hat": "cap", "hatc": "#e8e4dc", "pants": "#3a3a40", "moustache": "#5a5a5a", "stout": true }
    }
  },
  "uniques": {
    "plotter": {
      "name": "A cracked chartplotter",
      "icon": "plotter",
      "cat": "curio",
      "guide": 60,
      "cond": 1,
      "condLabel": "Cracked screen, still works",
      "questKey": true,
      "tells": [
        "A marine chartplotter, the screen cracked across one corner. It still boots.",
        { "text": "Its saved tracks loop out to the closed bed off Gannet Island, again and again, always after midnight.", "cls": "bad" }
      ]
    },
    "dinnerShell": {
      "name": "A scallop shell the size of a dinner plate",
      "icon": "bigshell",
      "cat": "curio",
      "guide": 45,
      "condLabel": "From the closed bed",
      "tells": ["A sea scallop that had thirty years to grow in peace. Somebody should frame it."]
    }
  },
  "scenes": {
    "joPlotter": {
      "title": "Jo Pinto pawns a chartplotter \"from a dumpster\"",
      "customer": "jo",
      "steps": [
        { "say": "jo", "text": "Found this in the dumpster behind the fish pier. It works, mostly. Forty?" },
        { "offer": { "unique": "plotter" }, "persona": "desperate", "asking": 40, "min": 25 },
        {
          "if": "offer != 'deal'",
          "then": [
            { "set": { "plotterOut": true } },
            { "say": "jo", "text": "Fine. It can go back in the dumpster. Where I found it." },
            { "leave": "jo" },
            { "end": true }
          ]
        },
        { "set": { "plotterIn": true } },
        { "say": "jo", "text": "Don't turn it on in the window, OK? Just... don't." },
        { "leave": "jo" }
      ]
    },
    "tessBed": {
      "title": "Tess: someone is running dark on the closed bed",
      "customer": "tess",
      "steps": [
        {
          "say": "tess",
          "text": [
            "Coffee filters, if you've got them. And a word, since you hear things at this counter.",
            "The bed off Gannet is closed. Three years, so the scallops can come back. Somebody's dragging it at night with their lights off. The fleet knows who, and nobody will say.",
            "If a chartplotter comes across your counter, I'd like to know."
          ]
        },
        { "find": "plotter", "in": "stock", "match": { "uniqueId": "plotter" } },
        {
          "if": "plotter",
          "then": [
            {
              "choose": [
                {
                  "label": "Show Tess the plotter",
                  "hint": "(she takes it; the story ends here)",
                  "then": [
                    { "take": "plotter" },
                    { "narrate": "Tess turns it on and scrolls through the tracks. Her face doesn't change, but when she gets to the end she goes back to the start." },
                    { "say": "tess", "text": "I know this boat. I'll deal with it. Thank you. Family's family, but the bed is everybody's." },
                    { "rep": 4 },
                    { "set": { "plotterEnd": "family", "plotterDone": true } }
                  ]
                },
                { "label": "Say nothing" }
              ]
            }
          ]
        },
        { "leave": "tess" }
      ]
    },
    "bentoPlotter": {
      "title": "Bento Raposo wants it back",
      "customer": "bento",
      "steps": [
        {
          "say": "bento",
          "text": [
            "Bento Raposo, the Constant Star. Word is a girl sold you a plotter. That's mine. Fell off my boat.",
            "I'll buy it back. A hundred and fifty, no questions. Generous, for something that fell off a boat."
          ]
        },
        {
          "choose": [
            {
              "label": "Sell it to Bento",
              "hint": "(+$150; the story ends here)",
              "then": [
                { "find": "plotter", "in": "stock", "match": { "uniqueId": "plotter" } },
                { "take": "plotter" },
                { "coin": 150, "why": "Sold the chartplotter to Bento Raposo" },
                { "set": { "plotterEnd": "sold", "plotterDone": true } },
                { "say": "bento", "text": "Pleasure. You never saw it." },
                { "leave": "bento" },
                { "end": true }
              ]
            },
            { "label": "\"It's not for sale.\"" }
          ]
        },
        { "say": "bento", "text": "Everything's for sale. You'll see." },
        { "leave": "bento" }
      ]
    },
    "joBack": {
      "title": "Jo comes clean",
      "customer": "jo",
      "steps": [
        {
          "say": "jo",
          "text": [
            "Bento came in, didn't he. It's not his. It's not from a dumpster either.",
            "I crew on the Bonnie Dee. I took the plotter off the dash because I wanted somebody to look at the tracks who isn't scared of the fleet. That's you, apparently.",
            "Come down to the pier one night. I'll plug it back in and you can see for yourself. It's going to rain. Wear a coat."
          ]
        },
        {
          "choose": [
            {
              "label": "\"I'll come.\"",
              "then": [
                { "set": { "plotterAboard": true } },
                { "toast": "Calendar: the Bonnie Dee, at the fish pier", "look": "jo" }
              ]
            },
            {
              "label": "\"Not my business, Jo.\"",
              "then": [{ "say": "jo", "text": "That's what everybody says." }]
            }
          ]
        },
        { "leave": "jo" }
      ]
    },
    "plotterWheelhouse": {
      "title": "The Bonnie Dee's wheelhouse in the rain",
      "steps": [
        {
          "stage": "bonnieWheelhouse",
          "actors": [
            { "id": "you", "cast": "keeper", "name": "You", "at": [120, 166] },
            { "id": "jo", "cast": "jo", "at": [200, 164], "facingLeft": true }
          ]
        },
        { "narrate": "The Bonnie Dee's wheelhouse, tied up at the fish pier. Rain runs down the glass. The sodium lamps outside make everything the color of weak tea." },
        { "say": "jo", "text": "Plugging it in. Look at the tracks, not at me." },
        { "narrate": "A green line leaves the pier at two in the morning, runs out to Gannet with no stops, loops back and forth across the closed bed, and comes home before five. Fourteen times since August." },
        { "narrate": "There's one saved waypoint that isn't on the bed. It's eleven miles out, labelled MARGARET RUTH. Somebody marked it a long time ago and never deleted it.", "if": "quest.radio" },
        {
          "say": "jo",
          "text": [
            "Kenny's boat. Kenny Bascombe. He's a good skipper and he's behind on the loan for her, and he's Tess's nephew.",
            "He goes out again this week. Thursday, probably. Come with us and see it. Then you'll know I'm not making it up."
          ]
        },
        { "set": { "plotterTrack": true } },
        { "toast": "Calendar: a night run on the Bonnie Dee", "look": "jo" }
      ]
    },
    "plotterRun": {
      "title": "Running dark off Gannet",
      "steps": [
        {
          "stage": "bonnieDeck",
          "actors": [
            { "id": "you", "cast": "keeper", "name": "You", "at": [110, 166] },
            { "id": "jo", "cast": "jo", "at": [150, 164] },
            { "id": "kenny", "cast": "kenny", "at": [240, 162], "facingLeft": true }
          ]
        },
        { "narrate": "Two in the morning, four miles out, every light on the boat switched off. The only glow aboard is the plotter in the wheelhouse window. The town is a thin line of lights behind you." },
        { "say": "kenny", "text": "Jo said you wanted to see a scallop boat at night. You picked a funny night. Hold onto something." },
        { "narrate": "The dredge comes up over the rail streaming water, heavy with scallops the size of saucers. Three years without anyone touching them." },
        { "say": "kenny", "text": "Look at that. You know what that's worth? I'm four payments behind on this boat. The bank doesn't care that the bed's closed." },
        { "say": "jo", "text": "Kenny, the bed's closed so there's something left for next year. For you, too." },
        {
          "choose": [
            {
              "label": "\"Your aunt is the harbormaster, Kenny.\"",
              "then": [
                { "say": "kenny", "text": "You think I don't know that? Every time I go past her shack I feel it." }
              ]
            },
            {
              "label": "\"How many more nights?\"",
              "then": [
                { "say": "kenny", "text": "Till the boat's paid off. Or till somebody tells her. Whichever comes first." }
              ]
            },
            { "label": "Say nothing" }
          ]
        },
        {
          "if": "hook.carryingPhoto",
          "note": "items in use (docs/ITEMS_IN_USE.md): proof that doesn't need the plotter",
          "then": [
            { "use": "photo", "as": "camera" },
            { "set": { "plotterPhoto": true } },
            { "narrate": "While Kenny is bent over the culling table you take three frames with the {camera.name|lower|or:camera}: the dredge, the haul, and the plotter's screen in the wheelhouse window with the date on it." }
          ]
        },
        { "narrate": "In the culling, one shell is bigger than all the others: a dinner plate, thirty years old at least. Kenny holds it out to you without a word." },
        { "if": "shelf.free", "then": [{ "add": { "unique": "dinnerShell" } }, { "refresh": "panel" }] },
        { "say": "jo", "text": "There's a hearing at the shack next week. Bento's complained about somebody. He doesn't know who. You'll be asked, if you're there." },
        { "set": { "plotterRun": true } },
        { "toast": "Calendar: the hearing at the harbormaster's shack", "look": "jo" }
      ]
    },
    "plotterHearing": {
      "title": "The hearing at the harbormaster's shack",
      "steps": [
        {
          "stage": "harbormasterNight",
          "actors": [
            { "id": "you", "cast": "keeper", "name": "You", "at": [100, 166] },
            { "id": "tess", "cast": "tess", "at": [230, 160], "facingLeft": true },
            { "id": "kenny", "cast": "kenny", "at": [150, 164] },
            { "id": "bento", "cast": "bento", "at": [280, 162], "facingLeft": true }
          ]
        },
        { "narrate": "The harbormaster's shack, after hours, with folding chairs. Six skippers, two coffee cups each, and Tess at the chart table with a notepad she hasn't written on." },
        { "say": "bento", "text": "Somebody's been on the closed bed. Everybody knows it. And this one's got a plotter that'll say who." },
        { "say": "tess", "text": "Is that right? Keeper, have you got something for this hearing?" },
        { "find": "plotter", "in": "stock", "match": { "uniqueId": "plotter" } },
        {
          "choose": [
            {
              "label": "Put the plotter on the table",
              "hint": "(Tess respects it; half the fleet won't)",
              "disabled": "!plotter",
              "then": [
                { "take": "plotter" },
                { "narrate": "Tess scrolls through the tracks in front of everybody. When she gets to the boat's name she reads it out in the same voice she uses for the tide tables." },
                { "say": "tess", "text": "Kenny Bascombe. Bonnie Dee. Fourteen trips on a closed bed. I'll write it up for the state tonight." },
                { "say": "kenny", "text": "Yeah. OK. Yeah." },
                { "rep": 6, "why": "Spoke up at the harbor hearing" },
                { "heat": -4 },
                { "set": { "plotterEnd": "hearing" } }
              ]
            },
            {
              "label": "Ask Tess for a word outside first",
              "disabled": "!plotter",
              "then": [
                { "take": "plotter" },
                { "narrate": "Outside, in the wind, you hand her the plotter. She looks at the name on the screen and closes her eyes." },
                { "say": "tess", "text": "Thank you for not doing it in there. I'll do it myself, tonight, to his face. Then I'll tell the state, and I'll lend him the payment, and he'll hate me for a year." },
                { "rep": 5, "why": "Took it to Tess quietly" },
                { "set": { "plotterEnd": "family" } }
              ]
            },
            {
              "label": "\"It went over the side. Sorry.\"",
              "hint": "(no evidence; Kenny owes you)",
              "disabled": "!plotter",
              "then": [
                { "take": "plotter" },
                { "say": "tess", "text": "Over the side. Of course it did. Hearing's closed, then. Nothing to hear." },
                { "narrate": "On the way out, Kenny holds the door for you, and says nothing, and doesn't have to." },
                { "set": { "plotterEnd": "overboard" } }
              ]
            },
            {
              "label": "Sell the waypoints to Bento after the hearing",
              "hint": "(+$200)",
              "disabled": "!plotter",
              "then": [
                { "take": "plotter" },
                { "narrate": "After the hearing, in the car park, Bento counts out two hundred dollars by the light of his phone." },
                { "say": "bento", "text": "Now I know where the bed is. And where the Bonnie Dee goes. That's worth two hundred twice over." },
                { "coin": 200, "why": "Sold the waypoints to Bento Raposo" },
                { "set": { "plotterEnd": "sold" } }
              ]
            },
            {
              "label": "\"I don't have anything.\"",
              "then": [
                { "say": "tess", "text": "Nothing, then. Meeting adjourned. The bed stays closed whether or not anyone respects it." },
                { "set": { "plotterEnd": "overboard" } }
              ]
            },
            {
              "label": "Put your photographs of the haul on the table",
              "hint": "(proof, plotter or no plotter)",
              "if": "flag.plotterPhoto",
              "then": [
                { "narrate": "Tess goes through them one at a time: the dredge, the scallops, the wheelhouse screen with the boat's name and the date. Nobody in the shack says anything until she does." },
                { "say": "tess", "text": "Bonnie Dee. On the closed bed. I'll write it up for the state tonight. Kenny, you can talk to me first, if you want." },
                { "rep": 6, "why": "Spoke up at the harbor hearing" },
                { "heat": -4 },
                { "set": { "plotterEnd": "hearing" } }
              ]
            }
          ]
        },
        { "set": { "plotterDone": true } }
      ]
    }
  },
  "beats": [
    { "at": "1-2", "cast": "jo", "scene": "joPlotter" },
    { "at": "1-4", "cast": "tess", "scene": "tessBed", "if": "!flag.plotterDone" },
    { "at": "2-1", "cast": "bento", "scene": "bentoPlotter", "if": "flag.plotterIn && !flag.plotterDone && hook.plotterHere" },
    { "at": "2-2", "cast": "jo", "scene": "joBack", "if": "flag.plotterIn && !flag.plotterDone && hook.plotterHere" }
  ],
  "nights": [
    {
      "id": "plotter-wheelhouse",
      "window": ["2-3", "3-1"],
      "if": "flag.plotterAboard && !flag.plotterDone",
      "scene": "plotterWheelhouse",
      "test": [{ "set": { "plotterAboard": true } }]
    },
    {
      "id": "plotter-run",
      "window": ["3-1", "3-4"],
      "if": "flag.plotterTrack && !flag.plotterDone",
      "scene": "plotterRun",
      "test": [{ "set": { "plotterTrack": true } }]
    },
    {
      "id": "plotter-hearing",
      "window": ["3-4", "4-4"],
      "if": "flag.plotterRun && !flag.plotterDone",
      "scene": "plotterHearing",
      "test": [{ "set": { "plotterRun": true } }, { "add": { "unique": "plotter" } }]
    }
  ],
  "calendar": [
    { "id": "plotter-wheelhouse", "night": "plotter-wheelhouse", "story": "plotter", "where": "The fish pier", "title": "The Bonnie Dee's plotter", "known": "flag.plotterAboard", "scene": "plotterWheelhouse" },
    {
      "id": "plotter-run",
      "night": "plotter-run",
      "story": "plotter",
      "where": "Off Gannet Island",
      "title": "Running dark",
      "known": "flag.plotterTrack",
      "scene": "plotterRun",
      "bring": ["photo", "warm"]
    },
    { "id": "plotter-hearing", "night": "plotter-hearing", "story": "plotter", "where": "The harbormaster's shack", "title": "The hearing", "known": "flag.plotterRun", "scene": "plotterHearing" }
  ],
  "epilogue": [
    { "line": "Kenny Bascombe lost his permit for a season and crewed for his aunt's friends. The bed off Gannet reopened in the spring, and it was full.", "if": "flag.plotterEnd == 'hearing'" },
    { "line": "Tess Bascombe paid her nephew's boat loan for three months and didn't speak to him for two. The bed off Gannet stayed closed, and stayed full.", "if": "flag.plotterEnd == 'family'" },
    { "line": "Nobody ran dark on the Gannet bed again. Kenny Bascombe brings you scallops every Friday, and won't take money for them.", "if": "flag.plotterEnd == 'overboard'" },
    { "line": "By the spring the closed bed off Gannet was empty. Half the fleet had found it. Nobody could say how.", "if": "flag.plotterEnd == 'sold'" }
  ],
  "outcome": "flag.plotterEnd"
});
